"""Compose unaltered game captures into review sheets and a local gallery."""
import json, pathlib, html
from PIL import Image, ImageDraw, ImageFont
out=pathlib.Path('docs/mission-15-evidence')
c=json.loads((out/'captures.json').read_text())
titles={'bois':'Depuis le sol','silhouettes':'Silhouettes et lisière','sous-bois':'Sous-bois','aerienne':'Vue élevée','vallee':'Vallée','rue':'Rue','jardinieres':'Grimpante en jardinière','fleurs-ruelle':'Fenêtres fleuries','printemps':'Printemps','automne':'Automne','hiver':'Hiver','vent-moyen':'Vent moyen','vent-fort':'Vent fort'}
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',18)
def sheet(ids,name):
    w,h=640,427
    canvas=Image.new('RGB',(w*2,(h+44)*len(ids)+42),'#14231e');d=ImageDraw.Draw(canvas)
    d.text((16,12),'Mission 14 fusionnée',font=font,fill='#dce7d6');d.text((w+16,12),'15A · captures du jeu',font=font,fill='#dce7d6')
    for i,key in enumerate(ids):
        y=42+i*(h+44)
        for j,v in enumerate(['m14','15a']):
            p=out/v/(key+'.jpg');im=Image.open(p).convert('RGB');im.thumbnail((w,h));canvas.paste(im,(j*w,y))
            d.text((j*w+14,y+h+10),titles[key],font=font,fill='#dce7d6')
    canvas.save(out/name,quality=88,optimize=True)
sheet(['bois','aerienne','fleurs-ruelle'],'comparison.jpg')
sheet(['printemps','automne','hiver'],'seasons.jpg')
pairs=[]
for key,title in titles.items():
    if (out/'m14'/f'{key}.jpg').exists():
        pairs.append(f'''<article><h2>{html.escape(title)}</h2><div class="pair"><figure><img src="m14/{key}.jpg" alt="{title}, Mission 14" loading="lazy"><figcaption>Mission 14 fusionnée</figcaption></figure><figure><img src="15a/{key}.jpg" alt="{title}, 15A" loading="lazy"><figcaption>15A · mêmes caméra et climat</figcaption></figure></div></article>''')
perf=''
if (out/'performance-summary.json').exists():
    summary=json.loads((out/'performance-summary.json').read_text())['summary']
    for r in summary:
        if r['variant']!='15a': continue
        a=next(a for a in summary if a['variant']=='m14' and a['id']==r['id'] and a['profile']==r['profile'])
        perf+=f"<tr><td>{r['profile']}</td><td>{titles[r['id']]}</td><td>{a['medianMs']:.1f}</td><td>{r['medianMs']:.1f}</td><td>{r['deltaPercent']:+.1f} %</td><td>{r['p95Ms']:.1f}</td><td>{r['peakMs']:.1f}</td></tr>"
page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth · revue 15A</title><style>
:root{color-scheme:dark;font:16px/1.6 system-ui;background:#101c17;color:#e2e7df}body{max-width:1400px;margin:auto;padding:28px}h1,h2,h3{font-weight:500;line-height:1.3}h1{font-size:clamp(30px,5vw,60px);margin-bottom:16px}h2{margin-top:42px}a{color:#c1dba6}p{max-width:950px}.tag{color:#c1dba6;letter-spacing:.12em;font-size:13px}figure{margin:0}img,video{width:100%;height:auto;border-radius:8px;background:#1e2f25}figcaption{font-size:13px;color:#bcc7b8;margin:7px 0 20px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{padding:9px;border-bottom:1px solid #435046;text-align:left}.scroll{overflow-x:auto}.links{display:flex;gap:20px;flex-wrap:wrap}select{padding:10px;font:inherit;background:#24332a;color:inherit;border:1px solid #728b70;border-radius:6px}@media(max-width:700px){body{padding:18px}.pair{grid-template-columns:1fr}th,td{padding:5px}}</style>
<header><p class="tag">ENDLESS EARTH · MISSION 15A · REVUE HUMAINE</p><h1>Une nature plus généreuse</h1><p>Couronnes plus amples, feuillage ajouré, fleurs dans les embrasures du village. Les 2 500 ancrages et la géographie de Mission 14 restent conservés. Arrêt avant 15B.</p><p>Images et vidéos du vrai moteur Three.js. Aucune illustration générée. Les stations fixes servent à comparer des lieux, sans les présenter comme une promenade continue. Les commandes ont été masquées pour ces prises seulement ; leur refonte appartient à 15C.</p><div class="links"><a href="../mission-15.md">Rapport complet</a><a href="performance-summary.json">Mesures complètes</a><a href="audit.json">Ombres et préservation</a><a href="runtime.json">Collisions et replis</a><a href="mobile-controls.png">Mobile · commandes existantes</a></div></header>
'''+''.join(pairs)+'''
<section><h2>Deux solutions procédurales examinées</h2><p>Le candidat en volumes seuls offre une masse continue, mais des surfaces lisses de près. L’hybride retenu retire des faces intérieures et ajoute des bouquets ajourés en périphérie. Les formes restent stylisées ; leur naturel et leur densité sont à apprécier humainement. Aucun modèle externe importé. Une variante entièrement ajourée reste disponible avec <code>?perf=1&amp;canopy=perforated</code> pour apprécier son compromis de coût.</p><div class="pair"><figure><img src="volume/bois.jpg" alt="Candidat en volumes seuls"><figcaption>Candidat · 560 triangles proches, 140 au loin</figcaption></figure><figure><img src="15a/bois.jpg" alt="Hybride retenu"><figcaption>Hybride · 331 triangles proches, 58 au loin ; instanciation par cellule</figcaption></figure></div></section>
<section><h2>Le compromis du feuillage entièrement ajouré</h2><p>Ce premier candidat reste consultable : il coûte davantage de triangles et de fragments. Sa campagne initiale dépassait +47 % dans les deux vues boisées en Équilibré sous SwiftShader. Il reste accessible dans le jeu diagnostic ; cette alternative artistique n’est pas supprimée. La variante allégée conserve les dimensions des couronnes. <a href="candidate-performance.json">Mesures du candidat</a>.</p><div class="pair"><figure><img src="candidate-hybrid-bois.jpg" alt="Premier candidat au cœur ajouré"><figcaption>Candidat entièrement ajouré · 632 triangles proches / 140 lointains</figcaption></figure><figure><img src="15a/bois.jpg" alt="Enveloppe allégée"><figcaption>Proposition 15A · 331 / 58, bouquets périphériques ajourés</figcaption></figure></div></section><section><h2>Le vent à vitesse normale</h2><p>Deux observations continues d’environ 45 secondes : clair, couvert, orageux, 15 secondes chacun. Boucle native, aucune accélération du temps. La capture vidéo est silencieuse ; aucun son n’a changé dans ce jalon.</p><div class="pair"><figure><video controls preload="metadata" src="m14-vent.webm" poster="m14/bois.jpg"></video><figcaption>Mission 14 · rendu logiciel</figcaption></figure><figure><video controls preload="metadata" src="15a-vent.webm" poster="15a/bois.jpg"></video><figcaption>15A · rendu logiciel</figcaption></figure></div></section>
<section><h2>Fleurs, références et saisons</h2><p>Les photos C16 et C24 déjà collectées montrent des jardinières, pots fleuris et végétaux conduits. Les nouveaux placements sont tous des interprétations artistiques dans les fenêtres procédurales, sans correspondance photographique bâtiment par bâtiment. Aucun ajout sur le pont ni collision dans la rue.</p><div class="pair"><figure><img src="../../docs/mission-13-evidence/references/C24.jpg" alt="Photo locale de pots fleuris sur des fenêtres"><figcaption>C24 · Jochen Jahnke · <a href="https://commons.wikimedia.org/wiki/File:F06.Angles.1364.JPG">Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a> · référence documentaire antérieure</figcaption></figure><figure><img src="15a/fleurs-hiver.jpg" alt="La jardinière en hiver"><figcaption>15A en hiver · fleurs et feuillage saisonniers absents</figcaption></figure></div><p><a href="../../docs/mission-13-evidence/catalog.json">Crédits et licences complets des références</a>. Arbres et fleurs : géométries originales du projet ; aucune photo n’est transformée en texture.</p></section>
<section><h2>Coûts mesurés</h2><p>SwiftShader logiciel, 960 × 640, DPR 1. Temps synchronisés avec lecture complète, 15 échantillons par scène/profil/version, trois passages alternés. Caméras et climat complet identiques, phase du vent comprise. Ce ne sont pas des FPS GPU physique ou Android. P95 et pics restent visibles.</p><div class="scroll"><table><thead><tr><th>Profil</th><th>Vue</th><th>M14 méd. ms</th><th>15A méd. ms</th><th>Écart</th><th>15A P95</th><th>15A pic</th></tr></thead><tbody>'''+perf+'''</tbody></table></div></section>
<section><h2>À valider</h2><p>Les couronnes vous paraissent-elles plus belles et assez denses depuis le sol et en hauteur ? Les fleurs enrichissent-elles les rues avec suffisamment de discrétion ? Le compromis de coût et les transitions entre niveaux de détail vous conviennent-ils ? Les données techniques ne remplacent pas cette appréciation sur votre appareil.</p><p>Limites : formes et floraisons génériques, forêt sans inventaire botanique local, ombres de couronnes approximées, interfaces existantes conservées, aucun appareil Android ou GPU physique mesuré ici. Neige, ciel, personnage, interface et signes de vie des jalons suivants restent en attente de votre accord.</p></section></html>'''
(out/'index.html').write_text(page)
print('Review sheets and gallery written')
